# High performance PostgreSQL function for Bunna Bank attendance reporting sql = """ CREATE OR REPLACE FUNCTION generate_daily_employee_attendance_detail_report( p_from DATE, p_to DATE, p_report_type VARCHAR, p_user_id INTEGER DEFAULT 1 ) RETURNS VOID AS $$ BEGIN -- Clear previous results for this user/session to avoid multi-user collision DELETE FROM generate_employee_attendance_details WHERE create_uid = p_user_id;
IF p_report_type = 'attendance_summary' THEN INSERT INTO generate_employee_attendance_details ( create_uid, write_uid, employee_id, employee_identification, employee_name, place_of_assignment, work_unit, job_title, worked_hours, payable_hours, leave_hours, late_time_hour, early_exit_hour, over_time_hour, pre_defined, acknowledged_lateness, pre_approved_early_checkout, acknowledged_early_checkout, force_checkout, working_hours, attendance_percentage, absent_hours, create_date, write_date ) SELECT p_user_id AS create_uid, p_user_id AS write_uid, emp.id AS employee_id, COALESCE(emp.employee_identification, '') AS employee_identification, COALESCE(emp.name, '') AS employee_name, COALESCE(ou.name, '') AS place_of_assignment, COALESCE(ou.name, '') AS work_unit, CASE WHEN pg_typeof(job.name)::text = 'jsonb' THEN COALESCE(job.name->>'en_US', job.name::text, '') ELSE COALESCE(job.name::text, '') END AS job_title, COALESCE(SUM(att.worked_hours), 0.0) AS worked_hours, (COALESCE(SUM(att.worked_hours), 0.0) + COALESCE(leave_agg.total_leave_hours, 0.0) + COALESCE(SUM(att.pre_defined_lateness), 0.0) + COALESCE(SUM(att.pre_approved_early_checkout), 0.0) + COALESCE(SUM(att.acknowledged_late), 0.0) + COALESCE(SUM(att.acknowledged_exit), 0.0)) AS payable_hours, COALESCE(leave_agg.total_leave_hours, 0.0) AS leave_hours, COALESCE(SUM(att.late_time_hour), 0.0) AS late_time_hour, COALESCE(SUM(att.early_exit_hour), 0.0) AS early_exit_hour, COALESCE(SUM(att.over_time_hour), 0.0) AS over_time_hour, COALESCE(SUM(att.pre_defined_lateness), 0.0) AS pre_defined, COALESCE(SUM(att.acknowledged_late), 0.0) AS acknowledged_lateness, COALESCE(SUM(att.pre_approved_early_checkout), 0.0) AS pre_approved_early_checkout, COALESCE(SUM(att.acknowledged_exit), 0.0) AS acknowledged_early_checkout, COUNT(CASE WHEN att.check_out_status = 'Force Checkout' OR att.is_force_checkout = TRUE THEN 1 END) AS force_checkout, COALESCE(exp_wh.total_wh, 0.0) AS working_hours, CASE WHEN COALESCE(exp_wh.total_wh, 0.0) > 0 THEN ROUND(CAST((LEAST(exp_wh.total_wh, COALESCE(SUM(att.worked_hours), 0.0) + COALESCE(leave_agg.total_leave_hours, 0.0) + COALESCE(SUM(att.pre_defined_lateness), 0.0) + COALESCE(SUM(att.pre_approved_early_checkout), 0.0) + COALESCE(SUM(att.acknowledged_late), 0.0) + COALESCE(SUM(att.acknowledged_exit), 0.0) ) / exp_wh.total_wh) * 100 AS numeric), 2) ELSE 0.0 END AS attendance_percentage, GREATEST(0.0, COALESCE(exp_wh.total_wh, 0.0) - ( COALESCE(SUM(att.worked_hours), 0.0) + COALESCE(leave_agg.total_leave_hours, 0.0) + COALESCE(SUM(att.pre_defined_lateness), 0.0) + COALESCE(SUM(att.pre_approved_early_checkout), 0.0) + COALESCE(SUM(att.acknowledged_late), 0.0) + COALESCE(SUM(att.acknowledged_exit), 0.0) )) AS absent_hours, NOW(), NOW() FROM hr_employee emp LEFT JOIN operating_unit ou ON emp.default_operating_unit_id = ou.id LEFT JOIN hr_job job ON emp.job_position = job.id LEFT JOIN hr_attendance att ON att.employee_id = emp.id AND att.check_in >= p_from::timestamp AND att.check_in <= (p_to + interval '1 day')::timestamp AND (att.active = TRUE OR att.active IS NULL) LEFT JOIN LATERAL ( SELECT SUM( CASE WHEN l.number_of_days > 0 THEN l.number_of_days * 8.0 WHEN l.number_of_hours > 0 THEN l.number_of_hours ELSE 8.0 END ) AS total_leave_hours FROM hr_leave l WHERE l.employee_id = emp.id AND l.state = 'validate' AND l.date_from::date <= p_to AND l.date_to::date >= p_from ) leave_agg ON TRUE LEFT JOIN LATERAL ( SELECT SUM( COALESCE( ( SELECT 0.0 FROM hr_leave l WHERE l.employee_id = emp.id AND l.state = 'validate' AND l.date_from::date <= d::date AND l.date_to::date >= d::date LIMIT 1 ), ( SELECT CASE WHEN rl.schedule_type = 'day_off' THEN 0.0 WHEN js.id IS NOT NULL THEN GREATEST(0.0, (js.end_time - js.start_time) - CASE WHEN js.has_lunch_break THEN COALESCE(js.lunch_duration, 1.0) ELSE 0.0 END) ELSE 8.0 END FROM job_position_roster_exception_line rl JOIN job_position_roster_exception re ON rl.roster_id = re.id LEFT JOIN job_shift js ON rl.shift_id = js.id WHERE (rl.employee_id = emp.id OR re.employee_id = emp.id) AND re.status = 'active' AND (re.active = TRUE OR re.active IS NULL) AND rl.date = d::date ORDER BY re.start_date DESC, re.id DESC LIMIT 1 ), ( SELECT GREATEST(0.0, (js.end_time - js.start_time) - CASE WHEN js.has_lunch_break THEN COALESCE(js.lunch_duration, 1.0) ELSE 0.0 END) FROM job_position_exception jpe JOIN job_shift js ON jpe.shift_id = js.id WHERE jpe.employee_id = emp.id AND jpe.status = 'active' AND (jpe.active = TRUE OR jpe.active IS NULL) AND jpe.start_date <= d::date AND (jpe.end_date IS NULL OR jpe.end_date >= d::date) ORDER BY jpe.start_date DESC, jpe.id DESC LIMIT 1 ), ( SELECT GREATEST(0.0, (COALESCE(js.end_time, lbe.end_time, 17.0) - COALESCE(js.start_time, lbe.start_time, 8.0)) - CASE WHEN COALESCE(js.has_lunch_break, lbe.has_lunch_break, FALSE) THEN COALESCE(js.lunch_duration, 1.0) ELSE 0.0 END) FROM location_based_exception lbe LEFT JOIN job_shift js ON lbe.shift_id = js.id WHERE (lbe.active = TRUE OR lbe.active IS NULL) AND (lbe.operating_unit = emp.default_operating_unit_id OR lbe.id IN ( SELECT location_exception_id FROM rel_location_exception_operating_unit WHERE operating_unit_id = emp.default_operating_unit_id )) AND lbe.start_date <= d::date AND (lbe.end_date IS NULL OR lbe.end_date >= d::date) LIMIT 1 ), CASE WHEN EXTRACT(DOW FROM d) BETWEEN 1 AND 5 THEN 8.0 WHEN EXTRACT(DOW FROM d) = 6 THEN (CASE WHEN ou.work_unit_type IN ('head_office', 'head_offices', 'ho', 'district', 'district_office', 'regional_office') THEN 4.0 ELSE 8.0 END) ELSE 0.0 END ) ) AS total_wh FROM generate_series(p_from, p_to, '1 day'::interval) d ) exp_wh ON TRUE WHERE emp.active = TRUE GROUP BY emp.id, emp.employee_identification, emp.name, ou.name, ou.work_unit_type, job.id, job.name, exp_wh.total_wh, leave_agg.total_leave_hours;
ELSE -- Daily Employee Attendance Detail mode (per-attendance row) INSERT INTO generate_employee_attendance_details ( create_uid, write_uid, employee_id, employee_identification, employee_name, job_title, job_grade, place_of_assignment, work_unit, manager_name, attendance_month, checkin_date, checkin_time, checkout_time, remarks, worked_hours, payable_hours, late_time_hour, early_exit_hour, over_time_hour, pre_defined, acknowledged_lateness, pre_approved_early_checkout, acknowledged_early_checkout, force_checkout, working_hours, create_date, write_date ) SELECT p_user_id AS create_uid, p_user_id AS write_uid, emp.id AS employee_id, COALESCE(emp.employee_identification, '') AS employee_identification, COALESCE(emp.name, '') AS employee_name, COALESCE(job.name, '') AS job_title, COALESCE(CAST(emp.job_position AS VARCHAR), 'XIV') AS job_grade, COALESCE(ou.name, '') AS place_of_assignment, COALESCE(ou.name, '') AS work_unit, COALESCE(mgr.name, '') AS manager_name, TO_CHAR(att.check_in, 'Mon-YYYY') AS attendance_month, att.check_in::date AS checkin_date, att.check_in AS checkin_time, att.check_out AS checkout_time, COALESCE(att.check_in_status, att.check_out_status, '') AS remarks, COALESCE(att.worked_hours, 0.0) AS worked_hours, (COALESCE(att.worked_hours, 0.0) + COALESCE(att.pre_defined_lateness, 0.0) + COALESCE(att.pre_approved_early_checkout, 0.0) + COALESCE(att.acknowledged_late, 0.0) + COALESCE(att.acknowledged_exit, 0.0)) AS payable_hours, COALESCE(att.late_time_hour, 0.0) AS late_time_hour, COALESCE(att.early_exit_hour, 0.0) AS early_exit_hour, COALESCE(att.over_time_hour, 0.0) AS over_time_hour, COALESCE(att.pre_defined_lateness, 0.0) AS pre_defined, COALESCE(att.acknowledged_late, 0.0) AS acknowledged_lateness, COALESCE(att.pre_approved_early_checkout, 0.0) AS pre_approved_early_checkout, COALESCE(att.acknowledged_exit, 0.0) AS acknowledged_early_checkout, CASE WHEN att.check_out_status = 'Force Checkout' OR att.is_force_checkout = TRUE THEN 1 ELSE 0 END AS force_checkout, COALESCE(att.worked_hours, 0.0) AS working_hours, NOW(), NOW() FROM hr_attendance att JOIN hr_employee emp ON att.employee_id = emp.id LEFT JOIN operating_unit ou ON emp.default_operating_unit_id = ou.id LEFT JOIN hr_job job ON emp.job_position = job.id LEFT JOIN hr_employee mgr ON emp.parent_id = mgr.id WHERE att.check_in >= p_from::timestamp AND att.check_in <= (p_to + interval '1 day')::timestamp AND (att.active = TRUE OR att.active IS NULL) AND emp.active = TRUE; END IF; END; $$ LANGUAGE plpgsql; """ env.cr.execute(sql)

# Shift-Aware High Performance Auto-Checkout PostgreSQL Function (3-Hour Grace Period & Shift End Capping) sql = """ CREATE OR REPLACE FUNCTION auto_checkout_all_employees() RETURNS void LANGUAGE plpgsql AS $$ DECLARE v_grace_hours NUMERIC := 3.0; BEGIN /* Read dynamic post-shift grace period from ir_config_parameter, defaulting to 3.0 hours if unconfigured */ SELECT COALESCE(value::numeric, 3.0) INTO v_grace_hours FROM ir_config_parameter WHERE key = 'hr_attendance.post_shift_grace_hours' LIMIT 1;
IF v_grace_hours IS NULL OR v_grace_hours <= 0 THEN v_grace_hours := 3.0; END IF;
WITH resolved_shifts AS ( SELECT ha.id AS att_id, ha.check_in, COALESCE( js_roster.start_time, js_static.start_time, lbe.start_time, 8.0 ) AS resolved_start_time, COALESCE( js_roster.end_time, js_static.end_time, lbe.end_time, 17.0 ) AS resolved_end_time, ( ( date_trunc('day', ha.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa') + (COALESCE(js_roster.start_time, js_static.start_time, lbe.start_time, 8.0)) * INTERVAL '1 hour' ) AT TIME ZONE 'Africa/Addis_Ababa' ) AT TIME ZONE 'UTC' AS shift_start_utc, ( ( date_trunc('day', ha.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa') + (COALESCE(js_roster.end_time, js_static.end_time, lbe.end_time, 17.0)) * INTERVAL '1 hour' ) AT TIME ZONE 'Africa/Addis_Ababa' ) AT TIME ZONE 'UTC' AS shift_end_utc FROM hr_attendance ha JOIN hr_employee he ON ha.employee_id = he.id LEFT JOIN job_position_roster_exception_line rline ON rline.employee_id = he.id AND rline.date = (ha.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa')::date AND rline.schedule_type = 'shift' LEFT JOIN job_shift js_roster ON rline.shift_id = js_roster.id LEFT JOIN job_position_exception jpe ON jpe.employee_id = he.id AND jpe.active = TRUE AND jpe.status = 'active' LEFT JOIN job_shift js_static ON jpe.shift_id = js_static.id LEFT JOIN location_based_exception lbe ON he.default_operating_unit_id = lbe.operating_unit AND lbe.active = TRUE WHERE ha.check_out IS NULL AND (ha.active = TRUE OR ha.active IS NULL) ) UPDATE hr_attendance ha SET /* Force checkout sets check_out to exact Shift End Time */ check_out = CASE WHEN ha.check_in < rs.shift_end_utc THEN rs.shift_end_utc ELSE ha.check_in + INTERVAL '8 hours' END,
/* Payable Worked Hours: Capped between MAX(check_in, shift_start) and MIN(check_out, shift_end) */ worked_hours = GREATEST(0.0, ROUND( ( EXTRACT( EPOCH FROM ( LEAST( CASE WHEN ha.check_in < rs.shift_end_utc THEN rs.shift_end_utc ELSE ha.check_in + INTERVAL '8 hours' END, rs.shift_end_utc ) - GREATEST(ha.check_in, rs.shift_start_utc) ) ) / 3600.0 )::numeric, 2 )),
check_out_status = 'Force Checkout', is_force_checkout = TRUE, write_date = NOW() FROM resolved_shifts rs WHERE ha.id = rs.att_id /* Midnight Verification: Close all shifts that have already ended */ AND NOW() >= rs.shift_end_utc;
END; $$ LANGUAGE plpgsql; """ env.cr.execute(sql)

# High-Performance Daily Absence Detection PostgreSQL Function sql = """ CREATE OR REPLACE FUNCTION detect_daily_employee_absences() RETURNS void LANGUAGE plpgsql AS $$ DECLARE p_date DATE := (NOW() AT TIME ZONE 'Africa/Addis_Ababa')::date - INTERVAL '1 day'; v_isodow INTEGER := EXTRACT(ISODOW FROM p_date); BEGIN /* ========================================================= Function: detect_daily_employee_absences() Purpose: Detects active employees who had no check-in and no approved leave. Inserts absence records into attendance_payroll_payload for payroll deduction. Full awareness of Saturday Half-Day (HO/District = 4h), leaves, and partial sessions. Execution: Triggered via Odoo 19 Scheduled Action daily at 09:30 AM (Addis Ababa time). ========================================================= */ -- 1. IDENTIFY FULL-DAY ABSENCES & RECORD APPROPRIATE PAYROLL PAYLOAD INSERT INTO attendance_payroll_payload ( employee_id, effective_date, hours, payload_type, state, display_name, create_uid, write_uid, create_date, write_date ) SELECT emp.id AS employee_id, p_date AS effective_date, CASE WHEN v_isodow = 6 AND (ou.work_unit_type IN ('head_office', 'district_office') OR ou.work_unit_type IS NULL) THEN 4.0 ELSE 8.0 END AS hours, 'absence' AS payload_type, 'draft' AS state, CASE WHEN v_isodow = 6 AND (ou.work_unit_type IN ('head_office', 'district_office') OR ou.work_unit_type IS NULL) THEN 'Saturday Half-Day Absence - ' || emp.name || ' (' || p_date::text || ')' ELSE 'Full Day Absence - ' || emp.name || ' (' || p_date::text || ')' END AS display_name, 1 AS create_uid, 1 AS write_uid, NOW() AS create_date, NOW() AS write_date FROM hr_employee emp LEFT JOIN operating_unit ou ON ou.id = emp.default_operating_unit_id WHERE emp.active = TRUE AND NOT EXISTS ( SELECT 1 FROM hr_attendance att WHERE att.employee_id = emp.id AND (att.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa')::date = p_date AND (att.active = TRUE OR att.active IS NULL) ) AND NOT EXISTS ( SELECT 1 FROM hr_leave l WHERE l.employee_id = emp.id AND l.state = 'validate' AND l.date_from::date <= p_date AND l.date_to::date >= p_date AND (l.request_unit_half IS NOT TRUE AND COALESCE(l.number_of_days, 1.0) >= 1.0) ) AND NOT EXISTS ( SELECT 1 FROM attendance_payroll_payload app WHERE app.employee_id = emp.id AND app.effective_date = p_date AND app.payload_type = 'absence' ) /* Exclude Days Off (Roster Exception Line Day Off, Static Exception Day Off, or Default Sunday Day Off) */ AND NOT EXISTS ( SELECT 1 FROM job_position_roster_exception_line rl JOIN job_position_roster_exception r ON rl.roster_id = r.id WHERE rl.employee_id = emp.id AND r.active = TRUE AND r.status = 'active' AND rl.date = p_date AND rl.schedule_type = 'day_off' ) AND NOT EXISTS ( SELECT 1 FROM job_position_exception jpe WHERE jpe.employee_id = emp.id AND jpe.active = TRUE AND jpe.status = 'active' AND NOT EXISTS ( SELECT 1 FROM job_position_roster_exception r2 WHERE r2.employee_id = emp.id AND r2.active = TRUE AND r2.status = 'active' AND r2.start_date <= p_date AND r2.end_date >= p_date ) AND (v_isodow = 7 OR jpe.day_off = p_date) ) AND NOT ( v_isodow = 7 AND NOT EXISTS ( SELECT 1 FROM job_position_roster_exception r3 WHERE r3.employee_id = emp.id AND r3.active = TRUE AND r3.status = 'active' AND r3.start_date <= p_date AND r3.end_date >= p_date ) AND NOT EXISTS ( SELECT 1 FROM job_position_exception jpe2 WHERE jpe2.employee_id = emp.id AND jpe2.active = TRUE AND jpe2.status = 'active' ) );
-- 2. IDENTIFY PARTIAL ABSENCES (MISSING HALF-DAY SESSION ON WEEKDAYS) IF v_isodow BETWEEN 1 AND 5 THEN INSERT INTO attendance_payroll_payload ( employee_id, effective_date, hours, payload_type, state, display_name, create_uid, write_uid, create_date, write_date ) SELECT emp.id AS employee_id, p_date AS effective_date, 4.0 AS hours, 'absence' AS payload_type, 'draft' AS state, 'Half Day Absence (Missing Session) - ' || emp.name || ' (' || p_date::text || ')', 1 AS create_uid, 1 AS write_uid, NOW() AS create_date, NOW() AS write_date FROM hr_employee emp JOIN ( SELECT att.employee_id, COUNT(att.id) AS session_count, COALESCE(SUM(att.worked_hours), 0.0) AS total_worked FROM hr_attendance att WHERE (att.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa')::date = p_date AND (att.active = TRUE OR att.active IS NULL) GROUP BY att.employee_id ) att_summary ON att_summary.employee_id = emp.id WHERE emp.active = TRUE AND att_summary.session_count = 1 AND att_summary.total_worked <= 4.5 AND NOT EXISTS ( SELECT 1 FROM hr_leave l WHERE l.employee_id = emp.id AND l.state = 'validate' AND l.date_from::date <= p_date AND l.date_to::date >= p_date ) AND NOT EXISTS ( SELECT 1 FROM attendance_payroll_payload app WHERE app.employee_id = emp.id AND app.effective_date = p_date AND app.payload_type = 'absence' ) AND NOT EXISTS ( SELECT 1 FROM job_position_roster_exception_line rl JOIN job_position_roster_exception r ON rl.roster_id = r.id WHERE rl.employee_id = emp.id AND r.active = TRUE AND r.status = 'active' AND rl.date = p_date AND rl.schedule_type = 'day_off' ); END IF;
END; $$ LANGUAGE plpgsql; """ env.cr.execute(sql)

# High-Performance Job Abandonment Detection PostgreSQL Function sql = """ CREATE OR REPLACE FUNCTION detect_job_abandonment_cases() RETURNS void LANGUAGE plpgsql AS $$ DECLARE v_offense_id INT; p_check_from DATE := (NOW() AT TIME ZONE 'Africa/Addis_Ababa')::date - INTERVAL '4 days'; p_today DATE := (NOW() AT TIME ZONE 'Africa/Addis_Ababa')::date; BEGIN /* ========================================================= Function: detect_job_abandonment_cases() Purpose: Detects employees absent for 3+ consecutive working days without approved leave, and automatically creates a discipline case for Job Abandonment. Execution: Triggered via Odoo 19 Scheduled Action daily at 03:00 AM (Addis Ababa time). ========================================================= */ SELECT id INTO v_offense_id FROM discipline_offense WHERE name ILIKE '%job abandonment%' OR name ILIKE '%unexcused absence%' LIMIT 1;
IF v_offense_id IS NOT NULL THEN INSERT INTO discipline_case ( employee_id, offense_id, description, reference, state, incident_date, create_uid, write_uid, create_date, write_date ) SELECT emp.id AS employee_id, v_offense_id AS offense_id, 'Automatically flagged by System Audit: Unexcused absence for 3+ consecutive working days.', 'JOB-ABANDON-' || emp.id || '-' || TO_CHAR(p_today, 'YYYYMMDD'), 'draft' AS state, p_today AS incident_date, 1 AS create_uid, 1 AS write_uid, NOW() AS create_date, NOW() AS write_date FROM hr_employee emp WHERE emp.active = TRUE AND NOT EXISTS ( SELECT 1 FROM discipline_case dc WHERE dc.employee_id = emp.id AND dc.reference LIKE 'JOB-ABANDON-%' AND dc.state NOT IN ('revoked', 'closed') AND dc.incident_date >= p_check_from ) AND ( SELECT COUNT(DISTINCT (att.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa')::date) FROM hr_attendance att WHERE att.employee_id = emp.id AND (att.check_in AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Addis_Ababa')::date >= p_check_from AND (att.active = TRUE OR att.active IS NULL) ) = 0 AND NOT EXISTS ( SELECT 1 FROM hr_leave l WHERE l.employee_id = emp.id AND l.state = 'validate' AND l.date_from::date <= p_today AND l.date_to::date >= p_check_from ); END IF;
END; $$ LANGUAGE plpgsql;
-- Automated Lunch and Shift-End Force Checkout PostgreSQL Engine CREATE OR REPLACE FUNCTION process_automated_force_checkouts() RETURNS VOID AS $$ BEGIN PERFORM auto_checkout_all_employees(); END; $$ LANGUAGE plpgsql; """ env.cr.execute(sql)
